app.get('/api/chat',(req,res)=> okKey(req)?apiChat(req,res):json(res,{ok:false,error:'Forbidden'},403));
app.post('/api/chat/send',(req,res)=> okKey(req)?apiSendMessage(req,res):json(res,{ok:false,error:'Forbidden'},403));
app.post('/api/chat/edit',(req,res)=> okKey(req)?apiEditMessage(req,res):json(res,{ok:false,error:'Forbidden'},403));
app.post('/api/chat/delete',(req,res)=> okKey(req)?apiDeleteMessage(req,res):json(res,{ok:false,error:'Forbidden'},403));
app.post('/api/chat/media',upload.single('file'),(req,res)=> okKey(req)?apiSendMedia(req,res):json(res,{ok:false,error:'Forbidden'},403));
app.post('/api/chat/dialog',(req,res)=> okKey(req)?apiDialogState(req,res):json(res,{ok:false,error:'Forbidden'},403));
app.get('/api/audit',(req,res)=> okKey(req)?apiAudit(req,res):json(res,{ok:false,error:'Forbidden'},403));
app.get('/file',(req,res)=> okKey(req)?fileProxy(req,res):res.status(403).send('Forbidden'));
app.get('/export',(req,res)=> okKey(req)?backup(req,res):json(res,{ok:false,error:'Forbidden'},403));
app.get('/import',(req,res)=> okKey(req)?html(res,importPage(req)):html(res,blocked(),403));
app.post('/import',(req,res)=> okKey(req)?restore(req,res):json(res,{ok:false,error:'Forbidden'},403));
app.post('/webhook',async(req,res)=>{ if(SECRET_TOKEN && req.headers['x-telegram-bot-api-secret-token']!==SECRET_TOKEN) return res.status(403).send('Forbidden'); try{await update(req,req.body); return json(res,{ok:true})}catch(e){console.error(e); await owner('⚠️ <b>Ошибка Render/Neon Bot</b>\n\n<code>'+esc(String(e))+'</code>'); return json(res,{ok:true,error:String(e)})} });
app.use((err,req,res,next)=>{if(err instanceof multer.MulterError)return json(res,{ok:false,error:err.code==='LIMIT_FILE_SIZE'?'Файл больше 20 МБ':err.message},400);console.error(err);return json(res,{ok:false,error:'Ошибка сервера'},500)});
app.listen(PORT,()=>console.log('FrodRobot running on port '+PORT));
setTimeout(()=>runAutoBackup().catch(e=>console.error('auto backup',e)),15000);
setInterval(()=>runAutoBackup().catch(e=>console.error('auto backup',e)),60*60*1000).unref();
